const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const x of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = x === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}
const arrays = [Object.freeze([])];
let layer = arrays;
for (let length = 1; length <= 4; length++) {
  const next = [];
  for (const prefix of layer) {
    for (const value of ['', 'x', '+x']) next.push(Object.freeze([...prefix, value]));
  }
  arrays.push(...next);
  layer = next;
}
let pairs = 0;
for (const a of arrays) {
  for (const b of arrays) {
    const script = diffLines(a, b);
    assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
    assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
    assert.equal(script.filter(e => e.op === 'equal').length, lcs(a, b));
    assert.deepEqual(diffLines(a, b), script);
    let inserted = false;
    for (const entry of script) {
      if (entry.op === 'equal') inserted = false;
      else if (entry.op === 'insert') inserted = true;
      else {
        assert.equal(entry.op, 'delete');
        assert.equal(inserted, false);
      }
    }
    // Independently expand each changed entry, then union touching intervals.
    for (const context of [0, 1, 2, 3]) {
      const intervals = [];
      for (let i = 0; i < script.length; i++) {
        if (script[i].op === 'equal') continue;
        const start = Math.max(0, i - context);
        const end = Math.min(script.length, i + 1 + context);
        const last = intervals[intervals.length - 1];
        if (last && start <= last[1]) last[1] = end;
        else intervals.push([start, end]);
      }
      const expected = intervals.map(([start, end]) => {
        const before = script.slice(0, start);
        const region = script.slice(start, end);
        const oldLines = region.filter(e => e.op !== 'insert').length;
        const newLines = region.filter(e => e.op !== 'delete').length;
        return {
          oldStart: before.filter(e => e.op !== 'insert').length + (oldLines ? 1 : 0),
          oldLines,
          newStart: before.filter(e => e.op !== 'delete').length + (newLines ? 1 : 0),
          newLines,
          lines: region.map(e => ({ equal: ' ', delete: '-', insert: '+' }[e.op]) + e.line),
        };
      });
      const hunks = unifiedHunks(a, b, { context });
      assert.deepEqual(hunks, expected);
      for (const h of hunks) { Object.freeze(h.lines); Object.freeze(h); }
      Object.freeze(hunks);
      const result = applyHunks(a, hunks);
      assert.deepEqual(result, b);
      assert.notEqual(result, a);
    }
    pairs++;
  }
}
assert.deepEqual(unifiedHunks(['a'], ['a']), []);
assert.deepEqual(unifiedHunks([], ['+first'], { context: 0 }), [
  { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['++first'] },
]);
assert.deepEqual(unifiedHunks(['-first'], [], { context: 0 }), [
  { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['--first'] },
]);
const original = Object.freeze(['a', 'b', 'c', 'd', 'e']);
const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
const malformed = [
  null, {}, { ...valid, oldStart: 0 }, { ...valid, newStart: 0 },
  { ...valid, oldStart: -1 }, { ...valid, oldStart: 1.5 },
  { ...valid, oldStart: NaN }, { ...valid, newLines: Infinity },
  { ...valid, oldLines: -1 }, { ...valid, newLines: -1 },
  { ...valid, oldStart: 7 }, { ...valid, newStart: 3 },
  { ...valid, oldLines: 2 }, { ...valid, newLines: 2 },
  { ...valid, lines: ['-wrong', '+B'] },
  { ...valid, lines: [' wrong'] },
  { ...valid, lines: ['?b', '+B'] },
  { ...valid, lines: [''] }, { ...valid, lines: [null] },
  { ...valid, lines: {} }, { ...valid, lines: [] },
  { ...valid, lines: ['-b', '-c', '+B'] },
  { ...valid, lines: ['-b', '+B', '+extra'] },
];
for (const bad of malformed) {
  assert.throws(() => applyHunks(original, [bad]), /hunk 0 does not apply/);
}
assert.throws(() => applyHunks(original, [valid, valid]), /hunk 1 does not apply/);
const later = { oldStart: 4, oldLines: 1, newStart: 4, newLines: 1, lines: ['-d', '+D'] };
assert.throws(() => applyHunks(original, [later, valid]), /hunk 1 does not apply/);
assert.deepEqual(applyHunks(original, [valid, later]), ['a', 'B', 'c', 'D', 'e']);
const inserted = { oldStart: 1, oldLines: 0, newStart: 2, newLines: 2, lines: ['+x', '+y'] };
assert.deepEqual(applyHunks(original, [inserted, { ...later, newStart: 6 }]),
  ['a', 'x', 'y', 'b', 'c', 'D', 'e']);
assert.throws(() => applyHunks(original, [inserted, later]), /hunk 1 does not apply/);
assert.deepEqual(applyHunks(['a', 'b'], [
  { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-a'] },
  { oldStart: 2, oldLines: 1, newStart: 0, newLines: 0, lines: ['-b'] },
]), []);
const gapInput = ['old1', 'a', 'b', 'old2'];
const gapOutput = ['new1', 'a', 'b', 'new2'];
assert.equal(unifiedHunks(gapInput, gapOutput, { context: 1 }).length, 1);
assert.equal(unifiedHunks(['old1', 'a', 'b', 'c', 'old2'], ['new1', 'a', 'b', 'c', 'new2'], { context: 1 }).length, 2);
for (const repetitive of [false, true]) {
  const a = Array.from({ length: 20000 }, (_, i) => repetitive ? String(i % 3) : `line ${i}`);
  const b = a.slice();
  b.splice(19000, 1);
  b.splice(10000, 1, 'replacement');
  b.splice(100, 0, 'added');
  const start = performance.now();
  const script = diffLines(a, b);
  assert.equal(script.filter(e => e.op !== 'equal').length, 4);
  const hunks = unifiedHunks(a, b);
  assert.deepEqual(applyHunks(a, hunks), b);
  const elapsed = performance.now() - start;
  assert.ok(elapsed < 1000, `20,000-line case took ${elapsed} ms`);
  console.log(`20,000-line ${repetitive ? 'repetitive' : 'unique'} roundtrip: ${elapsed.toFixed(2)} ms`);
}
console.log(`Passed ${pairs} exhaustive minimality/determinism cases, ${pairs * 4} hunk roundtrips, coordinate and malformed-hunk checks.`);

