 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let cursor = 0;
  for (let i = 0; i < hunks.length; i++) {
    const hunk = hunks[i];
    if (!hunk ||
        !Number.isSafeInteger(hunk.oldStart) ||
        !Number.isSafeInteger(hunk.newStart) ||
        !Number.isSafeInteger(hunk.oldLines) ||
        !Number.isSafeInteger(hunk.newLines) ||
        hunk.oldLines < 0 || hunk.newLines < 0 ||
        hunk.oldStart < (hunk.oldLines === 0 ? 0 : 1) ||
        hunk.newStart < (hunk.newLines === 0 ? 0 : 1) ||
        !Array.isArray(hunk.lines)) {
      throw new Error(`hunk ${i} does not apply`);
    }
    const oldIndex = hunk.oldStart - (hunk.oldLines === 0 ? 0 : 1);
    const newIndex = hunk.newStart - (hunk.newLines === 0 ? 0 : 1);
    if (oldIndex < cursor || oldIndex > a.length ||
        hunk.oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - cursor) {
      throw new Error(`hunk ${i} does not apply`);
    }
    while (cursor < oldIndex) result.push(a[cursor++]);

    let oldLines = 0;
    let newLines = 0;
    for (const line of hunk.lines) {
      if (typeof line !== 'string' ||
          (line[0] !== ' ' && line[0] !== '-' && line[0] !== '+')) {
        throw new Error(`hunk ${i} does not apply`);
      }
      const value = line.slice(1);
      if (line[0] !== '+') {
        if (oldLines >= hunk.oldLines || a[cursor] !== value) {
          throw new Error(`hunk ${i} does not apply`);
        }
        oldLines++;
        cursor++;
      }
      if (line[0] !== '-') {
        if (newLines >= hunk.newLines) {
          throw new Error(`hunk ${i} does not apply`);
        }
        newLines++;
        result.push(value);
      }
    }
    if (oldLines !== hunk.oldLines || newLines !== hunk.newLines) {
      throw new Error(`hunk ${i} does not apply`);
    }
  }
  while (cursor < a.length) result.push(a[cursor++]);
  return result;
}

